// Akses env publik untuk klien web (Aturan Teknis §5.3 & §10).
//
// Catatan: JANGAN impor `./env` (file autogenerated Varlock) dari kode web —
// modul tersebut menarik `varlock/env` yang bergantung pada `node:process`,
// sehingga gagal dibundel ke runtime Cloudflare/workerd. Env publik dibaca
// langsung dari `import.meta.env`, dan hanya variabel `VITE_*` (non-rahasia)
// yang boleh ada di sini.

export const ENV = {
  VITE_SERVER_URL: import.meta.env.VITE_SERVER_URL,
} as const;
